const EXPORT_SCALE = 2;
async function svgToPngBlob(svgText) {
  const doc = new DOMParser().parseFromString(svgText, 'image/svg+xml');
  const root = doc.documentElement;
  const evb = (root.getAttribute('viewBox') || '').split(/\s+/).map(Number);
  const w = (evb.length === 4 && evb[2] > 0) ? evb[2] : (svgContainer.clientWidth || 800);
  const h = (evb.length === 4 && evb[3] > 0) ? evb[3] : (svgContainer.clientHeight || 600);
  root.setAttribute('width', String(Math.round(w * EXPORT_SCALE)));
  root.setAttribute('height', String(Math.round(h * EXPORT_SCALE)));
  root.style.maxWidth = 'none';

  const svgUrl = URL.createObjectURL(new Blob(
    [new XMLSerializer().serializeToString(doc)],
    {type: 'image/svg+xml;charset=utf-8'},
  ));
  try {
    const img = new Image();
    await new Promise((resolve, reject) => {
      img.onload = resolve;
      img.onerror = () => reject(new Error('SVG 图像加载失败'));
      img.src = svgUrl;
    });
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(w * EXPORT_SCALE);
    canvas.height = Math.round(h * EXPORT_SCALE);
    const ctx = canvas.getContext('2d');
    // 填上容器背景色,避免透明底的 PNG 在深色主题/看图软件里发黑
    const bg = getComputedStyle(svgContainer).backgroundColor;
    ctx.fillStyle = (!bg || bg === 'rgba(0, 0, 0, 0)') ? '#ffffff' : bg;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    const blob = await new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
    if (!blob) throw new Error('PNG 编码失败');
    return blob;
  } finally {
    URL.revokeObjectURL(svgUrl);
  }
}

async function exportPng() {
  let blob;
  try {
    blob = await svgToPngBlob(svg);
  } catch (err) {
    // Safari 无法把含 foreignObject(htmlLabels)的 SVG 装进 Image/canvas,
    // 退回用纯 SVG 文本标签重新渲染一份专供导出,页面显示不受影响
    console.warn('原始 SVG 导出失败,改用 htmlLabels:false 重新渲染导出:', err);
    const directive = '%%{init: {"flowchart":{"htmlLabels":false},"class":{"htmlLabels":false}}}%%\n';
    const fm = /^---\r?\n[\s\S]*?\r?\n---\r?\n/.exec(source);
    const exportSource = fm
      ? source.slice(0, fm[0].length) + directive + source.slice(fm[0].length)
      : directive + source;
    const rerendered = await mermaid.render(id + '-export-' + Math.random().toString(36).slice(2), exportSource);
    blob = await svgToPngBlob(rerendered.svg);
  }
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = id + '.png';
  a.click();
  URL.revokeObjectURL(a.href);
}

